function [r, v] = fix_eci(r_e, v_e, jd)
%FIX_ECI  An Earth-fixed fix taken to J2000 at the Julian date jd: r = C' r_e, v = C' (v_e + w_E x r_e), C the onboard
%   eci2ecef at jd.
%   r_e: real[1][3] (passed a plain number)
%   v_e: real[1][3] (passed a plain number)
%   jd: real[1] (passed a plain number)
%   returns r: real[1][3] (passed a plain number)
%   returns v: real[1][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    r = zeros(3, 1);
    v = zeros(3, 1);
    c = asils.alg.frames.eci2ecef(jd);
    ve = (v_e + asils.pc.cross_([0; 0; 0.000072921158553], r_e));
    r = asils.alg.math.mat3t_vec(c, r_e);
    v = asils.alg.math.mat3t_vec(c, ve);
end
